/* ===== Botón circular de notas ===== */
.btn-notas {
    position: relative;
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: #2f323a;
    border: 1px solid #3d4048;
    color: #77eee6;           /* ← verde menta */
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.25s ease;
    text-decoration: none;
}

.btn-notas:hover {
    background: #3d4048;
    color: #a8f5f0;           /* ← verde claro al hover */
    transform: scale(1.05);
}

.btn-notas i {
    font-size: 16px;
}

/* ===== Campana con número dentro ===== */
.badge-campana {
    position: absolute;
    top: -4px;
    right: -4px;
    width: 25px;
    height: 25px;
    display: flex;
    align-items: center;
    justify-content: center;
    animation: pulso 1.8s infinite;
    border-radius: 50%;
}

/* La campana es la forma principal */
.badge-campana .fa-bell {
    left: 12px !important;
    position: absolute;
    inset: 0;
    font-size: 25px;
    color: #e74c3c;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    text-shadow: 0 0 3px rgba(0, 0, 0, 0.6);
}

/* El número dentro de la campana */
.badge-campana .numero {
    left: 7px !important;
    position: relative;
    z-index: 2;
    color: #ffffff;
    font-size: 10px;
    font-family: verdanab;
    transform: translateY(-1px);
}

/* ===== Animación de pulso (verde) ===== */
@keyframes pulso {
    0%   { box-shadow: 0 0 0 0 rgba(119, 238, 230, 0.7); }
    70%  { box-shadow: 0 0 0 6px rgba(119, 238, 230, 0); }
    100% { box-shadow: 0 0 0 0 rgba(119, 238, 230, 0); }
}

/* ===== Tooltip ===== */
.btn-notas .tooltip {
    position: absolute;
    bottom: -32px;
    right: 0;
    background: #000;
    color: #77eee6;           /* ← verde menta */
    font-size: 11px;
    padding: 4px 8px;
    border-radius: 4px;
    white-space: nowrap;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s;
}
.btn-notas:hover .tooltip {
    opacity: 1;
}

@keyframes notasSlideDown {
    from { opacity: 0; transform: translateY(-25px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ===== Pantallas muy pequeñas ===== */
@media (max-width: 360px) {
    #notasModalOverlay {
        padding: 50px 6px 16px !important;
    }
    .notas-modal-box {
        border-radius: 12px !important;
    }
    .notas-modal-head h3 {
        font-size: 15px !important;
    }
}
@keyframes notasSlideDown {
    from { opacity: 0; transform: translateY(-20px); }
    to   { opacity: 1; transform: translateY(0); }
}
