<div id="editar_controles" class="modal" data-easein="slideRightIn" data-backdrop="static" align="center">  
    <div class="modal-dialog modal-lg" style="z-index:9999!important;font-family:verdanab;font-size:14px;color:#333333">
        <div class="modal-content" style="border-radius:0px;background-color:#ffffff">
            <div class="modal-header">            
                <button type="button" class="close" data-dismiss="modal" aria-hidden="true" id="costum1"><span style=" font-size:22px!important" class="fa fa-times"></button>
            </div>
            <div class="modal-body" align="center" style="padding:2em">
                <p style="font-size:22px;line-height:1.5em;font-family:Moristonb;letter-spacing:2px">EDITAR SEGUIMIENTO</p>
                <input type="hidden" id="id_seguimiento"></input>
                <form name="form_seguimiento" id="form_seguimiento">
                    <div class="row" style="padding:2em"><br>
                        <div class="row">
                        <p style="font-family:verdanab;font-size:16px;text-align:left;color:#006699">Tipo de caso:</p>
                        <table style="width:100%">
                            <tr>
                                <td style="font-family:verdanab;font-size:14px">Caso confirmado&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp</td>
                                <td class="radio"> 
                                    <input type="radio" id="radio98" class ="R98" name ="R9" value="1"/>
                                    <label id="check4" for="radio98">
                                </td> 
                            </tr>
                            <tr>
                                <td style="font-family:verdanab;font-size:14px">Caso sintomático/No confirmado&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp</td>
                                <td class="radio"> 
                                    <input type="radio" id="radio99" class ="R99" name ="R9" value="2"/>
                                    <label id="check4" for="radio99">
                                </td> 
                            </tr>
                             <tr>
                                <td style="font-family:verdanab;font-size:14px">No caso&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp</td>
                                <td class="radio"> 
                                    <input type="radio" id="radio100" class ="R100" name ="R9" value="3"/>
                                    <label id="check4" for="radio100">
                                </td> 
                            </tr>
                        </table>
                        <table style="width:100%">
                            <tr>
                                <td colspan=2 style="font-family:verdanab;font-size:14px">Observación:&nbsp&nbsp&nbsp&nbsp&nbsp&nbsp</td>
                            </tr>
