<script>
document.addEventListener('DOMContentLoaded', function() {
    const botonesCarpeta = document.querySelectorAll('.btn-carpeta');
    const botonesSubcarpeta = document.querySelectorAll('.btn-subcarpeta');
    const paneles = document.querySelectorAll('.panel-contenido');
    // ⚠️ CAMBIO: Solo selecciona los data-toggle que NO son para modales
    const toggles = document.querySelectorAll('[data-toggle]:not([data-toggle="modal"])');

    function activarPanel(targetId) {
        paneles.forEach(panel => panel.classList.remove('activo'));
        const panelActivo = document.getElementById(targetId);
        if (panelActivo) panelActivo.classList.add('activo');
        botonesCarpeta.forEach(b => b.classList.remove('activo'));
        botonesSubcarpeta.forEach(b => b.classList.remove('activo'));
    }

    botonesCarpeta.forEach(boton => {
        if (!boton.hasAttribute('data-toggle')) {
            boton.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();
                const targetId = this.getAttribute('data-target');
                if (targetId) {
                    activarPanel(targetId);
                    this.classList.add('activo');
                    document.querySelectorAll('.submenu.abierto').forEach(sub => {
                        sub.classList.remove('abierto');
                        const toggle = document.querySelector(`[data-toggle="${sub.id}"]`);
                        if (toggle) {
                            const icon = toggle.querySelector('.toggle-icon i');
                            if (icon) {
                                icon.classList.remove('fa-chevron-down');
                                icon.classList.add('fa-chevron-right');
                            }
                        }
                    });
                }
            });
        }
    });

    botonesSubcarpeta.forEach(boton => {
        boton.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            const targetId = this.getAttribute('data-target');
            if (targetId) {
                activarPanel(targetId);
                this.classList.add('activo');
                const parentLi = this.closest('li').parentElement.closest('li');
                if (parentLi) {
                    const parentBtn = parentLi.querySelector('.btn-carpeta');
                    if (parentBtn) parentBtn.classList.add('activo');
                }
            }
        });
    });

    toggles.forEach(toggle => {
        toggle.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            const submenuId = this.getAttribute('data-toggle');
            const submenu = document.getElementById(submenuId);
            const icon = this.querySelector('.toggle-icon i');
            if (submenu) {
                submenu.classList.toggle('abierto');
                if (icon) {
                    icon.classList.toggle('fa-chevron-right');
                    icon.classList.toggle('fa-chevron-down');
                }
                if (submenu.classList.contains('abierto')) {
                    this.classList.add('activo');
                } else {
                    const subActiva = submenu.querySelector('.btn-subcarpeta.activo');
                    if (!subActiva) this.classList.remove('activo');
                }
            }
        });
    });

    const subActiva = document.querySelector('.btn-subcarpeta.activo');
    if (subActiva) {
        const parentSubmenu = subActiva.closest('.submenu');
        if (parentSubmenu) {
            parentSubmenu.classList.add('abierto');
            const parentToggle = parentSubmenu.closest('li').querySelector('[data-toggle]');
            if (parentToggle) {
                const icon = parentToggle.querySelector('.toggle-icon i');
                if (icon) {
                    icon.classList.remove('fa-chevron-right');
                    icon.classList.add('fa-chevron-down');
                }
                parentToggle.classList.add('activo');
            }
        }
    }

    window.abrirCarpeta = function(targetId) {
        const carpeta = document.querySelector(`.btn-carpeta[data-target="${targetId}"]`);
        if (carpeta) {
            carpeta.click();
        } else {
            const subCarpeta = document.querySelector(`.btn-subcarpeta[data-target="${targetId}"]`);
            if (subCarpeta) subCarpeta.click();
        }
    };

    console.log('✅ Sistema de carpetas inicializado correctamente');
    console.log(`📁 ${botonesCarpeta.length} carpetas principales encontradas`);
    console.log(`📂 ${botonesSubcarpeta.length} subcarpetas encontradas`);
    console.log(`📄 ${paneles.length} paneles de contenido encontrados`);
}); 
$(document).ready(function() {
    $('.individual').hide();
    $('#popup6').hide();
    $('#popup7').hide();
    var Codigo = '<?php echo $Codigo ?>';
    $(document).on('click', '.costos', function(e) {
        e.preventDefault();
        $('#costos_modal').modal('show');
        cargarCentrosCostoTabla();
    });
    function cargarCentrosCostoTabla() {
        var id_admin = '<?php echo $Codigo ?>';
        $('#tabla_centros_costos').html(`<tr><td colspan="3" style="padding:20px;text-align:center;font-family:verdana;">
            <i class="fa fa-spinner fa-spin" style="font-size:20px;color:#666;"></i>
            <span style="font-family:verdanab;color:#666;font-size:14px;margin-left:10px;">Cargando centros de costo...</span>
        </td></tr>`);
        $.ajax({
            type: "post",
            url: "../costos_auditivo.php",
            data: "id_admin=" + id_admin,
            success: function(response) {
                try {
                    const tasks = JSON.parse(response);
                    let template = '';
                    if (tasks && tasks.length > 0) {
                        tasks.forEach((task, index) => {
                            var nombre = task.Certificada || 'Sin nombre';
                            template += `<tr style="border:1px solid #71788e;background:#ffffff;">
                                <td style="padding:10px;border:1px solid #71788e;text-align:center;font-family:Verdanab;font-size:13px;">${index + 1}</td>
                                <td style="padding:10px;border:1px solid #71788e;text-align:left;font-family:Verdanab;font-size:13px;"><strong>${nombre}</strong></td>
                                <td id="borderout">
                                    <button class="btn-editar-centro-costo task" data-nombre="${nombre}" data-title="Editar" style="background:transparent;color:#000;border:none;padding:5px;border-radius:3px;cursor:pointer;transition: all 0.3s;font-size:16px;font-family:verdana;z-index:0!important;">
                                        <i class="fa fa-pencil" style="z-index:0!important"></i>
                                    </button>
                                </td>
                            </tr>`;
                        });
                    } else {
                        template = `<tr><td colspan="3" style="padding:40px 20px;text-align:center;font-family:verdana;">
                            <i class="fa fa-building" style="font-size:48px;color:#ccc;display:block;margin-bottom:15px;"></i>
                            <p style="color:#666;font-size:14px;">No hay centros de costo registrados</p>
                        </td></tr>`;
                    }
                    $('#tabla_centros_costos').html(template);
                } catch(e) {
                    console.error('Error al parsear JSON:', e);
                    $('#tabla_centros_costos').html(`<tr><td colspan="3" style="text-align:center;padding:20px;color:red;font-family:verdana;">
                        <i class="fa fa-exclamation-triangle" style="font-size:20px;"></i>
                        <p style="margin-top:10px;font-size:13px;">Error al cargar los centros de costo</p>
                    </td></tr>`);
                }
            },
            error: function() {
                $('#tabla_centros_costos').html(`<tr><td colspan="3" style="text-align:center;padding:20px;color:red;font-family:verdana;">
                    <i class="fa fa-exclamation-triangle" style="font-size:20px;"></i>
