    $(document).on('click', '.btn-editar-centro-costo', function() {
        var nombre = $(this).data('nombre');
        $('#edit_nombre_original').val(nombre);
        $('#edit_nombre_centro_costo').val(nombre);
        $('#modal_editar_centro_costo').modal('show');
    });
    $('#btn_guardar_edicion_centro').off('click').on('click', function() {
        var nombreOriginal = $('#edit_nombre_original').val();
        var nombreNuevo = $('#edit_nombre_centro_costo').val().trim();
        var id_admin = '<?php echo $Codigo ?>';
        if (!nombreNuevo) {
            alert('Por favor ingresa el nombre del centro de costo');
            $('#edit_nombre_centro_costo').focus();
            return;
        }
        var nombreExistente = false;
        var nombreActual = '';
        $('#tabla_centros_costos tr').each(function() {
            var celdaNombre = $(this).find('td:eq(1)');
            if (celdaNombre.length > 0) {
                nombreActual = celdaNombre.text().trim();
                if (nombreActual.toLowerCase() === nombreNuevo.toLowerCase() && nombreActual !== nombreOriginal) {
                    nombreExistente = true;
                }
            }
        });
        $.ajax({
            type: "post",
            url: "../guardar_centro_costo.php",
            data: {
                id_admin: id_admin,
                nombre_original: nombreOriginal,
                nombre_nuevo: nombreNuevo
            },
            success: function(response) {
                try {
                    var resultado = JSON.parse(response);
                    if (resultado.success) {
                        $('#modal_editar_centro_costo').modal('hide');
                        cargarCentrosCostoTabla();
                        alert('Centro de costo actualizado correctamente');
                    } else {
                        alert('Error: ' + (resultado.mensaje || 'No se pudo actualizar'));
                    }
                } catch(e) {
                    alert('Error al procesar la respuesta del servidor');
                    console.error('Error:', e);
                }
            },
            error: function() {
                alert('Error al actualizar el centro de costo');
            }
        });
    });
    $('#modal_editar_centro_costo').on('hidden.bs.modal', function() {
