    function procedimientos() {
        $.ajax({
            type: "post",
            url: "../text_auditivo.php",
            data: "Codigo=" + Codigo,
            success: function(response) {
                const tasks = JSON.parse(response);
                let Objetivo = '', Alcance = '', Definicion = '', Responsabilidades = '', Planear = '', Hacer = '', Verificar = '', Corregir = '';
                tasks.forEach(task => {
                    Objetivo = task.Objetivo || '';
                    Alcance = task.Alcance || '';
                    Definicion = task.Definicion || '';
                    Responsabilidades = task.Responsabilidades || '';
                    Planear = task.Planear || '';
                    Hacer = task.Hacer || '';
                    Verificar = task.Verificar || '';
                    Corregir = task.Corregir || '';
                });
                document.getElementById('objetivo').innerHTML = Objetivo;
                document.getElementById('alcance').innerHTML = Alcance;
                document.getElementById('definicion_T').innerHTML = Definicion;
                document.getElementById('responsabilidades_T').innerHTML = Responsabilidades;
                document.getElementById('planear').innerHTML = Planear;
                document.getElementById('hacer_P').innerHTML = Hacer;
                document.getElementById('verificar').innerHTML = Verificar;
                document.getElementById('corregir').innerHTML = Corregir;
                document.getElementById("objetivoE").value = Objetivo.replace(/<br[/][>]/g, "");
                document.getElementById("alcanceE").value = Alcance.replace(/<br[/][>]/g, "");
                document.getElementById("definicionE").value = Definicion.replace(/<br[/][>]/g, "");
                document.getElementById("responsabilidadesE").value = Responsabilidades.replace(/<br[/][>]/g, "");
                document.getElementById("planearE").value = Planear.replace(/<br[/][>]/g, "");
                document.getElementById("hacerE").value = Hacer.replace(/<br[/][>]/g, "");
                document.getElementById("verificarE").value = Verificar.replace(/<br[/][>]/g, "");
                document.getElementById("corregirE").value = Corregir.replace(/<br[/][>]/g, "");
            }
        });
    }
