    $("#form_capacitacion").submit(function(event) {
        event.preventDefault();
        var Titulo = $('#Titulo').val();
        var Dia1 = $('#Dia1').val();
        var Dia2 = $('#Dia2').val();
        var Hora1 = $('#Hora1').val();
        var Hora2 = $('#Hora2').val();
        var Acreditadas = $('#Acreditadas').val();
        var Modalidad = $('#Modalidad').val();
        var formatohora = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
        if (!(Hora1.match(formatohora) && Hora2.match(formatohora))) {
            return;
        }
        var formData = new FormData();
        formData.append("id_admin", id_admin);
        formData.append("Titulo", Titulo);
        formData.append("Dia1", Dia1);
        formData.append("Dia2", Dia2);
        formData.append("Hora1", Hora1);
        formData.append("Hora2", Hora2);
        formData.append("Acreditadas", Acreditadas);
        formData.append("Modalidad", Modalidad);
        formData.append("Descripcion", $('#Descripcion').val());
        formData.append("Destino", $('#Destino').val());
        formData.append("Responsable", $('#Responsable').val());
        formData.append("SVE", 1);
        $.ajax({
            url: '../escritor.inc.php',
            type: 'post',
            data: formData,
            contentType: false,
            processData: false,
            success: function(response) {
                document.form.reset();
                fetchTasks2();
            }
        });
    });
