    $(document).on('click', '.pdf_reporte', function(e) {
        const element = $(this).closest('tr');
        const id_paciente = element.attr('taskId1');
        const Genero0 = element.attr('taskId4');
        const Control1_0 = element.attr('taskId5');
        const Ips = element.attr('taskId6');
        const Direccion = element.attr('taskId7');
        const Horario = element.attr('taskId8');
        const Ciudad = element.attr('taskId9');
        const Paciente = element.attr('taskId3');
        var Genero = (Genero0 == "M") ? "SEÑOR" : "SEÑORA";
        var Control1 = new Date(Control1_0);
        var mes0 = Control1.getMonth() + 1;
        var meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
        var mes = meses[mes0 - 1] || '';
        var year = Control1.getFullYear();
        var doc = new jsPDF('p', 'pt', 'letter');
        var img = new Image();
        img.src = '../admin/<?php echo $Archivo2 ?>';
        doc.addImage(img, 'png', 90, 665, 90, 80);
        doc.setFontSize(12);
        doc.setFontType("bold");
        doc.text(80, 100, "Medellín, <?php echo $dia ?> de " + mes + " de " + year, { maxWidth: 445, align: 'justify', lineHeightFactor: 1.5 });
        doc.text(80, 130, Genero, { maxWidth: 445, align: 'justify', lineHeightFactor: 1.5 });
