            success: function(response) {
                const tasks = JSON.parse(response);
                let Template = '';
                tasks.forEach(task => {
                    Template += `<tr id="textarea" taskId1="${task.id}">
                        <td id="td">${task.Fecha}</td>
                        <td id="td">${task.Cedula}</td>
                        <td id="td">${task.Paciente}</td>
