                let Template = '';
                let Dosimetria_Pj = '';
                tasks.forEach(task => {
                    Template += `<tr style="height:3em">
                        <td id="td" style="font-family:verdanab!important;vertical-align:middle">Dosimetrías programadas</td>
                        <td id="td" style="text-align:center;font-family:verdanab!important;width:20%!important;vertical-align:middle">${task.Dosimetria_P}</td>
                    </tr> 
                    <tr style="height:3em">
                        <td id="td" style="font-family:verdanab!important;vertical-align:middle">Dosimetrías realizadas</td>
                        <td id="td" style="text-align:center;font-family:verdanab!important;width:20%!important;vertical-align:middle">${task.Dosimetria_R}</td>
                    </tr>
                    <tr style="height:3em">
                        <td id="td" style="font-family:verdanab!important;vertical-align:middle">Porcentaje de ejecución</td>
