                    </tr>`;
                    Dosimetria_Pj = task.Dosimetria_Pj || 0;
                });
                $('#dosimetrias').html(Template);
                var chart;
                var inputSE2 = [parseInt(Dosimetria_Pj)];
                var dataSE2 = [];
                var categories = [''];
                $.each(inputSE2, function(index, value) {
                    var color;
                    if (value >= 75) color = "#44e78e";
                    else if (value >= 50) color = "#f9f981";
                    else if (value < 50) color = "#fd3535";
                    dataSE2.push({ y: value, color: color });
                });
                chart = new Highcharts.Chart({
                    chart: { renderTo: "Dosimetria_P", type: "bar", height: 36, backgroundColor: false, padding: -1, margin: -1 },
                    title: { text: '' },
                    xAxis: { categories: categories },
                    yAxis: { title: { text: '' }, min: 0, minRange: 100, maxPadding: 0 },
                    legend: { enabled: false },
                    credits: { enabled: false },
                    exporting: { enabled: false },
                    plotOptions: { series: { stacking: 'normal', pointWidth: 40 } },
                    series: [{ name: '', data: dataSE2 }]
                });
            }
        });
    }
