    $('#boton_recursos').click(function(e) {     
            e.preventDefault();
            const archivo = $('#file-838')[0].files[0];
            if (!archivo) return alert('Selecciona archivo');
            $(this).prop('disabled', true).html('Subiendo...');
            $('<div class="progress mt-2"><div class="progress-bar" style="width: 0%">0%</div></div>')
                .insertAfter(this);
            const formData = new FormData();
            formData.append('file', archivo);
            formData.append('sve', 1);
            formData.append('id_admin', '<?php echo $id_admin ?>');
            formData.append('Recurso', $('#Recurso').val());
            formData.append('Descripcion', $('#Descripcion_r').val());
            $.ajax({
                url: '../insertar_recursos.php',
                type: 'POST',
                data: formData,
                contentType: false,
                processData: false,
                xhr: function() {
                    const xhr = new XMLHttpRequest();
                    xhr.upload.addEventListener('progress', function(e) {
                        if (e.lengthComputable) {
                            const percent = (e.loaded / e.total) * 100;
                            $('.progress-bar').css('width', percent + '%').text(percent.toFixed(0) + '%');
                        }
                    });
                    return xhr;
                },
                success: function(response) {
                        recursos();
                        $("#costumModal11").modal("hide");
                         document.getElementById("form_recursos").reset();
                       // alert(response);
                },
                error: function() {
                    alert('Error de conexión');
                },
                complete: function() {
                    $('#boton_recursos').prop('disabled', false).html('Guardar Recurso');
                    $('.progress').remove();
                }
            });
        });
