    recursos();
    function recursos() {
        var id_admin = '<?php echo $id_admin ?>';
        var id = '<?php echo $id ?>';
        $.ajax({
            type: "post",
            url: "../recursos.php",
            data: "id_admin=" + id_admin + "&sve=1&id=" + id,
            success: function(response) {
                const tasks = JSON.parse(response);
                let Recursos = '';
                tasks.forEach(task => {
                    Recursos += `<tr><td style="padding:0.6em;font-family:verdanab;font-size:14px;text-align:center;background:#e9fbfa!important;border:0!important"><span>${task.Recurso}</span></td></tr>
                    <tr taskId="${task.id}" taskId1="${task.Codigo}" taskId2="${task.Nombre}" taskId3="${task.Extension}" id="textarea">
                        <td style="border:0!important"><span style="text-align:left!important">${task.Nombre}</span>
                            <button class="eliminar_R" data-title="Eliminar" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-trash"></span></button>
                            <button class="editar_R" data-title="Editar" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-pencil"></span></button>
                            <button class="task-download-recurso" data-title="Descargar" style="float:right;left:0em"><span class="fa fa-download"></span></button>
                            <button class="task-visualizacion3" data-title="Ver el doc" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-arrows-alt"></span></button>
                        </td>
                    </tr>
                    <tr>
                        <td style="border:0!important;text-aling:left;font-family:verdanai">${task.Fecha}</td>
                    </tr>
                    <tr>
                        <td style="padding-bottom:2em!important;border:0!important;text-aling:left;font-family:verdana">${task.Descripcion}</td>
                    </tr>`;
                });
                $('#recursos').html(Recursos);
            }
        });
    }
    $('#boton_grupo').click(function(event) {
        event.preventDefault();
        var Codigo = '<?php echo $Codigo ?>';
        var formData = new FormData();
        formData.append('Codigo', Codigo);
        formData.append('Grupo', $('#Grupo').val());
        formData.append('Descripcion', $('#Descripcion').val());
        formData.append('Individual', $('#Individual').val());
        formData.append('Ambiental', $('#Ambiental').val());
        formData.append('Periodicidad', $('#Periodicidad').val());
        formData.append('Cantidad', $('#Cantidad').val());
        formData.append('Nivel', $('#Nivel').val());
        $.ajax({
            url: '../grupo_auditivo.php',
            type: 'post',
            data: formData,
            contentType: false,
            processData: false,
            success: function(response) {
                document.getElementById("form_grupoges").reset();
                $("#nuevo_grupo").modal("hide");
                grupoges();
                fetchTasks_Grupo_GES();
            }
        });
    });
