    $(document).on('click', '.eliminar_P', function(e) {
        e.preventDefault();
        const element = $(this).closest('tr');
        const id = element.attr('taskId1');
        const actividad = element.attr('taskId2');
        $("#costumModal1").modal("show");
        $('#id_C').html(id);
        $('#actividad_C').html(actividad);
        $(".delete").off('click').on('click', function() {
            var id_P = document.getElementById("id_C").innerHTML;
            $.ajax({
                type: "post",
                url: "../eliminar.php",
                data: "id_P=" + id_P,
                success: function(response) { planificacion(); consolidado(); }
            });
        });
    });
    $(document).on('click', '.editar_P', function(e) {
        const element = $(this).closest('tr');
        const id = element.attr('taskId1');
        $("#costumModal2").modal("show");
        $.ajax({
            type: "post",
            url: "../datosplanificacion.php",
            data: "id=" + id,
            success: function(response) {
                const tasks = JSON.parse(response);
                if (tasks.length > 0) {
                    var task = tasks[0];
                    document.getElementById("id_P_e").value = task.id || '';
                    document.getElementById("Actividades_P_e").value = task.Actividades || '';
                    document.getElementById("Responsabilidades_P_e").value = task.Responsabilidades || '';
                    document.getElementById("Periodicidad_P_e").value = task.Periodicidad || '';
                    document.getElementById("Observaciones_P_e").value = task.Observaciones || '';
                }
            }
        });
        $('#form_P_editar').off('submit').on('submit', function(e) {
            e.preventDefault();
            const postData = {
                id_P_e: $('#id_P_e').val(),
                Actividades_P_e: $('#Actividades_P_e').val(),
                Responsabilidades_P_e: $('#Responsabilidades_P_e').val(),
                Periodicidad_P_e: $('#Periodicidad_P_e').val(),
                Observaciones_P_e: $('#Observaciones_P_e').val()
            };
            $.post('../editarcronograma.php', postData, function(response) {
                planificacion();
                consolidado();
                $("#costumModal2").modal("hide");
            });
        });
    });
