    function Porcentaje_cronograma() {
        var Codigo = '<?php echo $Codigo ?>';
        var id_admin = '<?php echo $id_admin ?>';
        $.ajax({
            type: "post",
            url: "../porcentaje_cronograma.php",
            data: "Codigo=" + Codigo + "&id_admin=" + id_admin,
            success: function(response) {
                const tasks = JSON.parse(response);
                if (tasks.length > 0) {
                    var task = tasks[0];
                    $('#porcentaje_0').html(task.Porcentaje0 || 0);
                    $('#porcentaje_1').html(task.Porcentaje1 || 0);
                    $('#porcentaje_2').html(task.Porcentaje2 || 0);
                    $('#porcentaje_3').html(task.Porcentaje3 || 0);
                    $('#porcentaje_4').html(task.Porcentaje4 || 0);
                    $('#porcentaje_5').html(task.Porcentaje5 || 0);
                }
            }
        });
    }
