    indicadores()
    function indicadores() {
        var Codigo = '<?php echo $Codigo ?>';
        var id_admin = '<?php echo $id_admin ?>';
        $.ajax({
            type: "post",
            url: "../item_indicadores_audio.php",
            data: "Codigo=" + Codigo + "&id_admin=" + id_admin,
            success: function(response) {
                const tasks = JSON.parse(response);
                let indicadoresHTML = '';
                tasks.forEach(task => {
                    indicadoresHTML += `<tr id="textarea" taskId="${task.Tipo}" taskId1="${task.id}" taskId2="${task.Tipo}" style="font-family:verdana;text-align:left">
                        <td style="font-family:verdanab">${task.Tipo}<br>
                            <button class="eliminar_In" data-title="Eliminar" style="float:left;left:0em"><span class="fa fa-trash"></span></button>
                            <button class="editar_In" data-title="Editar" style="float:left;left:1em"><span class="fa fa-pencil"></span></button>
                            <button class="grafica_In" data-title="Tendencias" style="float:left;left:2em"><span class="fa fa-line-chart"></span></button>
                        </td>
                        <td style="text-align:left">${task.Definicion}</td>
                        <td style="text-align:left">${task.Interpretacion}</td>
                        <td style="text-align:left">${task.Fuente}</td>
                        <td style="text-align:center">${task.Indicador} = <div class="fraction"><span class="fup">${task.Numerador}</span><span class="bar">/</span> <span class="fdn">${task.Denominador}</span></span></div> * 100</td>
                        <td style="text-align:center;vertical-align:middle!important"><button class="I1" style="color:#006699;font-family:verdana!important;font-size:13px!important">${task.Meta}%</button></td>
                        <td style="text-align:center;vertical-align:middle!important">${task.Resultado}%</td>
                    </tr>`;
                });
                $('#indicadores').html(indicadoresHTML);
            }
        });
    }
    function consolidado() {
        var Codigo = '<?php echo $Codigo ?>';
        $.ajax({
            type: "post",
            url: "../consolidado_cronograma_audio.php",
            data: "Codigo=" + Codigo,
            success: function(response) {
                const tasks = JSON.parse(response);
                if (tasks.length > 0) {
                    var task = tasks[0];
                    $('#total_enero').html(task.total_enero || 0);
                    $('#total_febrero').html(task.total_febrero || 0);
                }
            }
        });
    }
