    $('#boton_elementos').click(function(event) {
        event.preventDefault();
        var id_admin = <?php echo $id_admin ?>;
        var Elemento = $('#Elemento').val();
        var Elemento_titulo = $('#Elemento_titulo').val();
        var formData = new FormData();
        var files = $('#file-836')[0].files[0];
        if (!files) return alert('Selecciona archivo');
        $(this).prop('disabled', true).html('Subiendo...');
        $('<div class="progress mt-2"><div class="progress-bar" style="width: 0%">0%</div></div>')
            .insertAfter(this);
        formData.append('file',files);
        formData.append('id_admin',id_admin);
        formData.append('sve',1);
        formData.append('Elemento',Elemento);
        formData.append('Elemento_titulo',Elemento_titulo);
        $('#content').html('<div class="loading"><img src="../imagine/carga6.gif" style="margin-top:20%" /></div>');
        $.ajax({
            url: '../insertar_img.php',
            type: 'post',
            data: formData,
            contentType: false,
            processData: false,
            xhr: function() {
                const xhr = new XMLHttpRequest();
                xhr.upload.addEventListener('progress', function(e) {
                    if (e.lengthComputable) {
                        const percent = (e.loaded / e.total) * 100;
                        $('.progress-bar').css('width', percent + '%').text(percent.toFixed(0) + '%');
                    }
                });
                return xhr;
            },
            success: function(response) {
                $("#costumModal20").modal("hide");
                Tasks_img();
                document.getElementById("form_elementos").reset();
            },
            rror: function() {
                alert('Error de conexión');
            },
            complete: function() {
                $('#boton_elementos').prop('disabled', false).html('Guardar Recurso');
                $('.progress').remove();
            }
        });
        return false;
    });
    $(document).on('click', '.eliminar_img', (e) => {
        e.preventDefault();
        const element = $(this)[0].activeElement.parentElement.parentElement;
        const Codigo_img = $(element).attr('taskId');
        $.ajax({
            type: "post",
            url: "../eliminar.php",
            data: "Codigo_img=" + Codigo_img,
            success: function(response) {
                Tasks_img();
            }
        });
    });
    function Tasks_img() {
        var id_admin = <?php echo $id_admin ?>;
        $.ajax({
            type: "post",
            url: "../tasks32.php",
            data: "id_admin=" + id_admin + "&sve=" + 1,
            success: function(response) {
                const tasks = JSON.parse(response);
                let template = '';
                tasks.forEach(task => {
                    template += `<div taskId="${task.Codigo}"><div id="textarea"><p style="font-size:18px;font-family:verdanab">${task.Elemento_titulo}</p><p style="font-size:15px;font-family:verdana">${task.Elemento}</p><p><img src="../files/${task.Codigo}" id="foto_empleado"></img></p><br><button class="eliminar_img" data-title="Eliminar" style="text-align:center"><span class="fa fa-trash" style="font-size:22px!important"></span></button><br><br></div></div>`
                });
                $('#imagen').html(template);
            }
        });
    }
