        var id_admin = <?php echo $id_admin ?>;
        var formData = new FormData();
        var files = $('#file-837')[0].files[0];
        formData.append('file',files);
        formData.append('sve',1);
        formData.append('id_admin',id_admin);
        $('#content3').html('<div class="loading"><img src="../imagine/carga6.gif" style="margin-top:20%" /></div>');
        $.ajax({
            url: '../insertar_doc.php',
