    $(document).on('click', '.task-download-doc', (e) => {
        e.preventDefault();
        const element = $(this)[0].activeElement.parentElement.parentElement;
        const item = $(element).attr('taskId2');
        const nombre = $(element).attr('taskId3');
        const req = new XMLHttpRequest();
        req.responseType = "arraybuffer";
        req.onload = function onload() {
            const type = this.getResponseHeader('Content-Type');
            const jpegData = this.response;
            const blob = new Blob([jpegData], { type });
            const reader = new FileReader();
            reader.onload = e => {
                const anchor = document.createElement('a');
                anchor.style.display = 'none';
                anchor.href = e.target.result;
                anchor.download = nombre;
                anchor.click();
            };
            reader.readAsDataURL(blob);
        };
        req.onreadystatechange = () => {
            if(req.readyState === XMLHttpRequest.OPENED) {
                req.setRequestHeader('Accept', 'image/jpeg','image/jpg','image/png');
                req.send();
            }
        };
        req.open('get', "https://www.cedisalud.com.co/files/"+item);
    });
