    function Tasks_doc() {
        var id_admin = <?php echo $id_admin ?>;
        var id= <?php echo $id ?>;
        $.ajax({
            type: "post",
            url: "../tasks27.php",
            data: "id_admin=" + id_admin + "&id=" + id +"&sve=" + 1,
            success: function(response) {
                const tasks = JSON.parse(response);
                let template = '';
                tasks.forEach(task => {
                    template += `<tr id="textarea" taskId="${task.id}" taskId2="${task.Codigo}" taskId3="${task.Nombre}" taskId4="${task.Extension}">
                        <td style="font-family:verdanab;text-align:left;width:6%"><img src="https://www.cedisalud.com.co/imagine/${task.Extension}.png" width="28"/></a></td>
                        <td style="font-family:verdanab;text-align:left"><a href="" data-toggle="modal" class="task-download-doc enlace">${task.Nombre}</a></td>
                        <td style="color:#666666;font-family:verdanabi;width:30%;font-size:13px">${task.Fecha_registro}</td>
                        <td style="width:6%!important"><button class="task-visualizacion2" data-title="Ver el doc"><span class="fa fa-arrows-alt" style="font-size:20px!important;display:${task.Boton2}"></span></button></td>
                        <td id="borderout" style="padding:1em;width:6%!important"><button class="task-download-doc" data-title="Editar" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-download" style="font-size:20px!important"></span></button></td>
                        <td id="borderout" style="padding:1em;width:6%!important"><button class="eliminar-documento" title="Eliminar"><span class="fa fa-trash" style="font-size:20px!important;display:${task.Boton2}"></span></button></td>
                    </tr> `
                });
                $('#documentos_DM').html(template);
            }
        });
    }
