    $('#boton_recursos_formacion').click(function(event) {
        event.preventDefault();
        var id_admin = '<?php echo $id_admin ?>';
        var Recurso_formacion = $('#Recurso_formacion').val();
        var Descripcion_formacion = $('#Descripcion_formacion').val();
        var formData = new FormData();
        var files = $('#file-839')[0].files[0];
        if (!files) return alert('Selecciona archivo');
        $(this).prop('disabled', true).html('Subiendo...');
        $('<div class="progress mt-2"><div class="progress-bar" style="width: 0%">0%</div></div>')
            .insertAfter(this);
        formData.append('file',files);
        formData.append('sve',1);
        formData.append('id_admin',id_admin);
        formData.append('Recurso_formacion',Recurso_formacion);
        formData.append('Descripcion_formacion',Descripcion_formacion);
        $.ajax({
            url: '../insertar_recursos_formacion.php',
            type: 'post',
            data: formData,
            contentType: false,
            processData: false,
            xhr: function() {
                const xhr = new XMLHttpRequest();
                xhr.upload.addEventListener('progress', function(e) {
                    if (e.lengthComputable) {
                        const percent = (e.loaded / e.total) * 100;
                        $('.progress-bar').css('width', percent + '%').text(percent.toFixed(0) + '%');
                    }
                });
                return xhr;
            },
            success: function(response) {
                document.getElementById("form_recursos_formacion").reset();
                $("#costumModal24").modal("hide");
                recursos_formacion();
            },
            error: function() {
                alert('Error de conexión');
            },
            complete: function() {
                $('#boton_recursos').prop('disabled', false).html('Guardar Recurso');
                $('.progress').remove();
            }
        });
    });
    $(document).on('click', '.editar_R_F', (e) => {
        const element = $(this)[0].activeElement.parentElement.parentElement;
        const id = $(element).attr('taskId');
        $("#costumModal25").modal("show");
        $.ajax({
            type: "post",
            url: "../datosrecursos_formacion.php",
            data: "id=" + id,
            success: function (response) {
                const tasks = JSON.parse(response);
                let id= '';
                let Recurso= '';
                let Descripcion= '';
                tasks.forEach(task => {
                    id += `${task.id}`,
                    Recurso += `${task.Recurso}`,
                    Descripcion += `${task.Descripcion}`
                });
                document.getElementById("id_F_e").value = (id);
                document.getElementById("Recursos_F_e").value = (Recurso);
                document.getElementById("Descripcion_r_F_e").value = (Descripcion);
