    function recursos_formacion() {
        var id_admin = '<?php echo $id_admin ?>';
        $.ajax({
            type: "post",
            url: "../recursos_formacion.php",
            data: "id_admin=" + id_admin + "&sve=" + 1,
            success: function (response) {
                const tasks = JSON.parse(response);
                let Recursos = '';
                tasks.forEach(task => {
                    Recursos += `<tr><td style="padding:0.6em;font-family:verdanab;font-size:14px;text-align:center;background:#e9fbfa!important;border:0!important"><span>${task.Recurso}</span></td></tr>
                        <tr taskId="${task.id}" taskId1="${task.Codigo}" taskId2="${task.Nombre}" taskId3="${task.Extension}" id="textarea">
                            <td style="border:0!important"><span style="text-align:left!important">${task.Nombre}</span><button class="eliminar_R_F" data-title="Eliminar" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-trash"></span></button>  <button class="editar_R_F" data-title="Editar" style="float:right;left:0em;display:${task.Boton2}"><span class="fa fa-pencil"></span></button><button class="task-download-recurso-F" data-title="Descargar" style="float:right;left:0em"><span class="fa fa-download"></button></td>
                        </tr>
                        <tr>
                            <td style="border:0!important;text-aling:left;font-family:verdanai">${task.Fecha}</td>
                        </tr>
                        <tr>
                            <td style="padding-bottom:2em!important;border:0!important;text-aling:left;font-family:verdana">${task.Descripcion}</td>
                        </tr>`
                });
                $('#recursos_formacion').html(Recursos);
            },
        });
    }
