    $(document).on('click', '.editar_G', (e) => {
        const element = $(this)[0].activeElement.parentElement.parentElement;
        const id_grupo = $(element).attr('taskId');
        const grupo = $(element).attr('taskId3');
        $("#editar_grupo").modal("show");
        $.ajax({
            type: "post",
            url: "../grupoges3_auditivo.php",
            data: "grupo=" + grupo + "&id_grupo=" + id_grupo,
            success: function (response) {
                const tasks = JSON.parse(response);
                let id= '';
                let Grupo= '';
                let Descripcion= '';
                let Individual= '';
                let Ambiental= '';
                let Periodicidad= '';
                let Cantidad= '';
                let Nivel= '';
                tasks.forEach(task => {
                    id += `${task.id}`
                    Grupo += `${task.Grupo}`
                    Descripcion += `${task.Descripcion}`
                    Individual += `${task.Individual}`
                    Ambiental += `${task.Ambiental}`
                    Periodicidad += `${task.Periodicidad}`
                    Cantidad += `${task.Cantidad}`
                    Nivel += `${task.Nivel}`
                });
                document.getElementById("id_ges").value = (id);
                document.getElementById("Grupo_e").value = (Grupo);
                document.getElementById("Descripcion_e").value = (Descripcion);
                document.getElementById("Individual_e").value = (Individual);
                document.getElementById("Ambiental_e").value = (Ambiental);
                document.getElementById("Periodicidad_e").value = (Periodicidad);
                document.getElementById("Cantidad_e").value = (Cantidad);
                document.getElementById("Nivel_e").value = (Nivel);
                $('#form_G_editar').submit(e => {
                    e.preventDefault();
                    id_ges = $('#id_ges').val();
                    const postData = {
                        id_ges_auditivo:id_ges,
                        Grupo_e:$('#Grupo_e').val(),
                        Descripcion_e:$('#Descripcion_e').val(),
                        Individual_e:$('#Individual_e').val(),
                        Ambiental_e:$('#Ambiental_e').val(),
                        Periodicidad_e:$('#Periodicidad_e').val(),
                        Cantidad_e:$('#Cantidad_e').val(),
                        Nivel_e:$('#Nivel_e').val(),
                    };
                    const url = '../editarcronograma.php';
                    $.post(url, postData, (response) => {
                        grupoges();
                        $("#editar_grupo").modal("hide");
                    });
                });
            }
        });
    });
