        const id = $(element).attr('taskId');
        const Grupo = $(element).attr('taskId3');
        $("#costumModal16").modal("show");
        $('#id_G').html(id);
        $('#Grupo_G').html(Grupo);
        $(".delete").on('click', function(event) {
            var id_G_auditivo = document.getElementById("id_G").innerHTML;
            $.ajax({
                type: "post",
                url: "../eliminar.php",
