    function grupoges() {
        var id_admin = '<?php echo $id_admin ?>';
        var Codigo = '<?php echo $Codigo ?>';
        $.ajax({
            type: "post",
            url: "../grupoges_auditivo.php",
            data: "Codigo=" + Codigo + "&id_admin=" + id_admin,
            success: function (response) {
                const tasks = JSON.parse(response);
                let Grupoges = '';
                tasks.forEach(task => {
                    Grupoges += `<tr taskId="${task.id}" taskId1="${task.Codigo}" taskId2="${task.Promedio}" taskId3="${task.Grupo_n}" taskId4="${task.Grupo}">
                        <td style="padding:0.6em;font-family:verdanab;text-align:left" ><button class="task-ges" style="font-family:verdanab;font-size:13px;border:0!important;background:transparent!important;text-align:left;width:100%!important">${task.Grupo_n}</button><br><br><button class="eliminar_G" data-title="Eliminar" style="font-size:15px;border:0;background:transparent!important;float:right;left:0;display:${task.Boton2}"><span class="fa fa-trash"></span></button>&nbsp&nbsp&nbsp<button class="editar_G" data-title="Editar" style="font-size:15px;background:transparent!important;;border:0;float:right;left:0;display:${task.Boton2}"><span class="fa fa-pencil"></span></button></td>
                        <td>${task.Descripcion}</td>
                        <td>${task.Individual}</td>
                        <td>${task.Ambiental}</td>
                        <td>${task.Periodicidad}</td>
                        <td style="text-align:center;font-family:verdanab">${task.Cantidad}</td>
                        <td style="text-align:center;font-family:verdanab">${task.Nivel}</td>
                    </tr>`
                });
                $('#grupoges_').html(Grupoges);
            },
        });
    }
