document.addEventListener('DOMContentLoaded', function() {
    
    // === DETECTAR SI ES MÓVIL ===
    function isMobile() {
        return window.innerWidth <= 768;
    }

    // === FUNCIÓN PARA HACER SCROLL ===
    function scrollToTarget(targetId) {
        if (!targetId) return;
        
        // Eliminar '#' si existe
        var id = targetId.replace('#', '');
        var target = document.getElementById(id);
        
        if (target) {
            // Pequeño retraso para que el DOM se actualice
            setTimeout(function() {
                target.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start',
                    inline: 'nearest'
                });
            }, 300);
        }
    }

    // === CAPTURAR CLIC EN CARPETAS (btn-carpeta) ===
    document.querySelectorAll('.btn-carpeta').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            if (!isMobile()) return;
            
            // Buscar el data-target o href
            var target = this.getAttribute('data-target') || this.getAttribute('href');
            
            // Si es un modal o enlace interno
            if (target && target.startsWith('#')) {
                scrollToTarget(target);
            }
        });
    });

    // === CAPTURAR CLIC EN SUBCARPETAS (btn-subcarpeta) ===
    document.querySelectorAll('.btn-subcarpeta').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            if (!isMobile()) return;
            
            var target = this.getAttribute('data-target') || this.getAttribute('href');
            
            if (target && target.startsWith('#')) {
                scrollToTarget(target);
            }
        });
    });

    // === CAPTURAR CLIC EN ENLACES DEL SIDEBAR ===
    document.querySelectorAll('.sidebar-menu-central a, .btn-filtro, .btn-form-central').forEach(function(link) {
        link.addEventListener('click', function(e) {
            if (!isMobile()) return;
            
            var target = this.getAttribute('href') || this.getAttribute('data-target');
            
            if (target && target.startsWith('#')) {
                // Para modales, esperar a que se abra el modal
                if (target.includes('Modal') || target.includes('modal')) {
                    // El scroll se hará cuando el modal esté visible
                    var modalId = target;
                    var modal = document.querySelector(modalId);
                    
                    if (modal) {
                        // Escuchar cuando el modal se muestre
                        $(modal).on('shown.bs.modal', function() {
                            scrollToTarget(modalId);
                        });
                    }
                } else {
                    scrollToTarget(target);
                }
            }
        });
    });

    // === CAPTURAR CAMBIOS EN EL SELECTOR DEL HEADER ===
    document.querySelectorAll('.select-popup-wrapper input[type="radio"]').forEach(function(radio) {
        radio.addEventListener('change', function() {
            if (!isMobile()) return;
            
            // El cambio de sistema puede recargar contenido
            // Esperar un momento y hacer scroll al contenedor principal
            setTimeout(function() {
                var container = document.getElementById('container2') || 
                               document.querySelector('.contenido-columna') ||
                               document.querySelector('.panel-lateral');
                
                if (container) {
                    container.scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            }, 500);
        });
    });

    // === DETECTAR CAMBIO DE TAMAÑO DE PANTALLA ===
    var resizeTimer;
    window.addEventListener('resize', function() {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function() {
            // Si cambia de móvil a escritorio o viceversa
            // No hacer nada especial, solo actualizar estado
        }, 250);
    });

    // === FUNCIÓN PARA HACER SCROLL AL PANEL ACTIVO ===
    function scrollToActivePanel() {
        if (!isMobile()) return;
        
        var activePanel = document.querySelector('.panel-contenido.activo');
        if (activePanel) {
            setTimeout(function() {
                activePanel.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            }, 400);
        }
    }

    // === OBSERVAR CAMBIOS EN PANELES ===
    var observer = new MutationObserver(function(mutations) {
        mutations.forEach(function(mutation) {
            if (mutation.type === 'attributes' && 
                mutation.attributeName === 'class') {
                var el = mutation.target;
                if (el.classList.contains('activo')) {
                    scrollToActivePanel();
                }
            }
        });
    });

    // Observar todos los paneles
    document.querySelectorAll('.panel-contenido').forEach(function(panel) {
        observer.observe(panel, {
            attributes: true,
            attributeFilter: ['class']
        });
    });

    // === PARA BOTONES DE CARPETA CON TOGGLE ===
    document.querySelectorAll('.btn-carpeta, .btn-subcarpeta').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            if (!isMobile()) return;
            
            // Si el botón tiene toggle, esperar a que se abra el submenú
            var submenu = this.nextElementSibling;
            if (submenu && submenu.classList.contains('submenu')) {
                setTimeout(function() {
                    submenu.scrollIntoView({
                        behavior: 'smooth',
                        block: 'nearest'
                    });
                }, 350);
            }
        });
    });
});
document.addEventListener('DOMContentLoaded', function() {
     $('nav .scroll[href^="#"]').click(function () {
                var destino = $(this.hash);
                if (destino.length == 0) {
                    destino = $('a[name="' + this.hash.substr(1) + '"]');
                }
                if (destino.length == 0) {
                    destino = $('html');
                }
                $('html, body').animate({scrollTop: destino.offset().top}, 500);
                return false;
            });
    var nav = document.querySelector('nav');
    var isMobile = window.innerWidth <= 768;
    if (isMobile) {
        nav.style.display = 'none';
    }
    document.querySelectorAll('.btn-carpeta, .btn-subcarpeta').forEach(function(btn) {
        btn.addEventListener('click', function() {
            if (window.innerWidth <= 768) {
                nav.style.display = 'block';
                
                // Ocultar después de 3 segundos
                clearTimeout(window.navTimeout);
                window.navTimeout = setTimeout(function() {
                    nav.style.display = 'none';
                }, 3000);
            }
        });
    });
    document.querySelectorAll('.sidebar-menu-central a, .btn-filtro, .btn-form-central').forEach(function(link) {
        link.addEventListener('click', function() {
            if (window.innerWidth <= 768) {
                nav.style.display = 'block';
                
                clearTimeout(window.navTimeout);
                window.navTimeout = setTimeout(function() {
                    nav.style.display = 'none';
                }, 3000);
            }
        });
    });
    var contenido = document.querySelector('.contenido-columna');
    if (contenido) {
        contenido.addEventListener('scroll', function() {
            if (window.innerWidth <= 768) {
                nav.style.display = 'block';
                
                clearTimeout(window.navTimeout);
                window.navTimeout = setTimeout(function() {
                    nav.style.display = 'none';
                }, 2000);
            }
        });
    }
    window.addEventListener('resize', function() {
        if (window.innerWidth > 768) {
            nav.style.display = 'block';
        } else {
            nav.style.display = 'none';
        }
    });
});
// Abrir el modal al cargar la página y traer las notas
window.addEventListener('load', function () {
    // document.getElementById('notasModalOverlay').style.display = 'flex';
    cargarNotas();
});

// Cerrar con ESC
document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') {
        document.getElementById('notasModalOverlay').style.display = 'none';
    }
});

// ============================================================
// ============ CARGAR NOTAS ==================================
// ============================================================
function cargarNotas() {
    var Codigo = '<?php echo $Codigo ?>';
    const lista    = document.getElementById('notasLista');
    const contador = document.getElementById('notasContador');      // ← Total de notas
    const pendientes = document.getElementById('notasPendientes'); // ← Solo pendientes
    const Pve      = 1; // ← ahora es 1

    $.post('../leer_notas.php', { Codigo: Codigo, Pve: Pve }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;

            if (!res.ok) {
                console.error('Error:', res.error);
                return;
            }

            lista.innerHTML = '';

            // ===== Actualizar los dos conteos =====
            contador.textContent   = res.total;       // Total de notas (id_admin + Pve)
            pendientes.textContent = res.pendientes;  // Solo Diligenciada = 0

            if (res.notas.length === 0) {
                lista.innerHTML = '<div style="text-align:center;color:#999;font-size:13px;padding:20px 0;">No hay notas registradas</div>';
                return;
            }

            res.notas.forEach(function (n) {
                // ==== COLORES VERDES SEGÚN DILIGENCIADA ====
                const diligenciada = Number(n.Diligenciada) === 1;
                const bgColor     = diligenciada ? '#eafaf1' : '#fdecea';  // verde muy claro vs rojo muy claro
                const borderColor = diligenciada ? '#77eee6' : '#e74c3c';  // verde menta vs rojo

                const nota = document.createElement('div');
                nota.style.cssText = 'display:flex;justify-content:space-between;align-items:flex-start;gap:10px;' +
                    'background:' + bgColor + ';' +
                    'border-left:3px solid ' + borderColor + ';' +
                    'border-radius:8px;padding:10px 12px;margin-bottom:8px;font-size:14px;line-height:1.4;';
                nota.dataset.id = n.id;

                // === Contenido ===
                const span = document.createElement('span');
                span.style.cssText = 'flex:1;word-break:break-word;';
                let contenido = n.Nota;

                if (n.Observacion && n.Observacion.trim() !== '') {
                    contenido += '<br><small style="color:#555;font-size:12px;display:block;margin-top:4px;">' +
                                 '<i class="fa fa-comment" style="color:' + borderColor + '"></i> ' +
                                 n.Observacion + '</small>';
                }

                contenido += '<br><small style="color:#999;font-size:11px;">' + n.Fecha_registro + '</small>';
                span.innerHTML = contenido;

                // === Botones ===
                const btnContainer = document.createElement('div');
                btnContainer.style.cssText = 'display:flex;gap:4px;align-items:flex-start;';

                // Botón eliminar
                const btnEliminar = document.createElement('button');
                btnEliminar.innerHTML = '&times;';
                btnEliminar.title = 'Eliminar nota';
                btnEliminar.style.cssText = 'background:transparent;border:none;color:#999;font-size:18px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnEliminar.onmouseover = function () { this.style.color = '#e74c3c'; };
                btnEliminar.onmouseout  = function () { this.style.color = '#999'; };
                btnEliminar.onclick     = function () { eliminarNota(n.id, nota); };

                // Botón observación
                const btnObs = document.createElement('button');
                btnObs.innerHTML = '<i class="fa fa-comment"></i>';
                btnObs.title = 'Agregar observación';
                btnObs.style.cssText = 'background:transparent;border:none;color:#999;font-size:14px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnObs.onmouseover = function () { this.style.color = '#77eee6'; };
                btnObs.onmouseout  = function () { this.style.color = '#999'; };
                btnObs.onclick     = function () { agregarObservacion(n.id); };

                // Botón confirmar
                const btnConfirmar = document.createElement('button');
                btnConfirmar.innerHTML = '<i class="fa fa-check"></i>';
                btnConfirmar.title = 'Confirmar (marcar como diligenciada)';
                btnConfirmar.style.cssText = 'background:transparent;border:none;color:#999;font-size:14px;line-height:1;cursor:pointer;padding:0 4px;transition:color 0.2s;';
                btnConfirmar.onmouseover = function () { this.style.color = '#27ae60'; };
                btnConfirmar.onmouseout  = function () { this.style.color = '#999'; };
                btnConfirmar.onclick     = function () { confirmarNota(n.id); };

                btnContainer.appendChild(btnEliminar);
                btnContainer.appendChild(btnObs);
                btnContainer.appendChild(btnConfirmar);

                nota.appendChild(span);
                nota.appendChild(btnContainer);
                lista.appendChild(nota);
            });

        } catch (e) {
            console.error('Respuesta inválida:', response);
        }
    });
}

// ============================================================
// ============ AGREGAR NOTA ==================================
// ============================================================
function agregarNota() {
    var Codigo = '<?php echo $Codigo ?>';
    const notas = $('#notasInput').val().trim();
    if (notas === '') {
        $('#notasInput').focus();
        return;
    }
    const postData = {
        Codigo: Codigo,
        notas: notas,
        Pve: 1      // ← ahora es 1
    };
    $.post('../insertar_notas.php', postData, function (response) {
        console.log(response);
        $('#notasInput').val('');
        cargarNotas();
    });
}

// ============================================================
// ============ ELIMINAR NOTA =================================
// ============================================================
function eliminarNota(id, elemento) {
    if (!confirm('¿Eliminar esta nota?')) return;

    $.post('../eliminar_nota.php', { id: id }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                elemento.remove();
                actualizarContador();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}

// ============================================================
// ============ ACTUALIZAR CONTADOR ===========================
// ============================================================
function actualizarContador() {
    const total = document.querySelectorAll('#notasLista > div[data-id]').length;
    document.getElementById('notasContador').textContent = total;
}

// ============================================================
// ============ AGREGAR OBSERVACIÓN ===========================
// ============================================================
function agregarObservacion(id) {
    const obs = prompt('Escribe la observación:');
    if (obs === null) return;
    if (obs.trim() === '') {
        alert('La observación no puede estar vacía');
        return;
    }

    $.post('../actualizar_observacion.php', { id: id, observacion: obs.trim() }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                cargarNotas();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}

// ============================================================
// ============ CONFIRMAR NOTA ================================
// ============================================================
function confirmarNota(id) {
    if (!confirm('¿Marcar esta nota como diligenciada?')) return;

    $.post('../confirmar_nota.php', { id: id }, function (response) {
        try {
            const res = (typeof response === 'string') ? JSON.parse(response) : response;
            if (res.ok) {
                cargarNotas();
            } else {
                alert('Error: ' + res.error);
            }
        } catch (e) {
            console.error(response);
        }
    });
}
